import "server-only";
import { createHash } from "node:crypto";
import { supabaseAdmin } from "@/lib/supabase-admin";

const BUCKET = "documents";
const KEY_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

/**
 * Storage keys are random UUIDs generated by the server. They are never built
 * from anything a user typed. This check means that even if a database row were
 * tampered with, a key like "../../other" could not be used.
 */
function assertKey(key: string) {
  if (!KEY_RE.test(key)) throw new Error("invalid storage key");
}

export function sha256Hex(data: Buffer): string {
  return createHash("sha256").update(data).digest("hex");
}

export async function putObject(key: string, data: Buffer, contentType: string) {
  assertKey(key);
  const { error } = await supabaseAdmin.storage
    .from(BUCKET)
    .upload(key, data, { contentType, upsert: false });
  if (error) throw error;
}

export async function getObject(key: string): Promise<Buffer> {
  assertKey(key);
  const { data, error } = await supabaseAdmin.storage.from(BUCKET).download(key);
  if (error || !data) throw error ?? new Error("empty download");
  return Buffer.from(await data.arrayBuffer());
}

/** Best-effort cleanup after a failed insert. Never throws. */
export async function removeObject(key: string) {
  try {
    assertKey(key);
    await supabaseAdmin.storage.from(BUCKET).remove([key]);
  } catch (e) {
    console.error("could not remove orphaned object:", e);
  }
}